recommendations.queryStructure:
mutation BulkImport($input: BulkImportInput!) {
  bulkImport(input: $input) {
    success
    processedCount
    errors { message line }
    progress { total processed percentage }
  }
}

subscription SystemMonitoring {
  systemMetrics {
    timestamp
    cpu { usage percentage }
    memory { used total percentage }
    database { connections queries_per_second }
  }
}

query ValidateData($options: ValidationOptions) {
  validateDataIntegrity(options: $options) {
    isValid
    issues {
      type
      severity
      message
      affectedNodes
    }
    summary {
      totalChecks
      passedChecks
      failedChecks
    }
  }
}

